using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Reports that authentication code wasn't delivered via SMS to the specified phone number; for official mobile applications only
    /// </summary>
    public Task<TdLib.TdApi.Objects.Ok> ReportPhoneNumberCodeMissingAsync(string mobileNetworkCode = default)
    {

           using var activity =  StartCallActivity("ReportPhoneNumberCodeMissingAsync", typeof(ReportPhoneNumberCodeMissing).FullName ?? "ReportPhoneNumberCodeMissingAsync");

           try
           {
             return client.ReportPhoneNumberCodeMissingAsync(mobileNetworkCode);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
